// Updated App.js
import React, { useEffect, useState } from "react";
import {
  BrowserRouter as Router,
  Routes,
  Route,
  Navigate,
} from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { setAuthToken } from "./redux/root/api";
import { loadFromStorage } from "./redux/auth/authSlice";
import UserForm from "./components/user/UserForm";
import UserList from "./components/user/UserList";
import Layout from "./components/layout";
import Login from "./components/login/Login";
import Signup from "./components/login/Signup";
import ProtectedRoute from "./components/login/ProtectedRoute";
import AdminRoute from "./components/login/AdminRoute";
import Home from "./components/home/Home"; // You need to create this

function App() {
  const dispatch = useDispatch();
  const [isInitialized, setIsInitialized] = useState(false);

  const token = useSelector((state) => state.auth.token);
  const roles = useSelector((state) => state.auth.roles || []);

  useEffect(() => {
    // Load auth state from localStorage
    const storedToken = localStorage.getItem("token");
    if (storedToken) {
      setAuthToken(storedToken);
      dispatch(loadFromStorage());
    }
    setIsInitialized(true);
  }, [dispatch]);

  if (!isInitialized) {
    return (
      <div className="d-flex justify-content-center align-items-center min-vh-100">
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Loading...</span>
        </div>
      </div>
    );
  }

  return (
    <Router>
      <Routes>
        {/* Public routes */}
        <Route path="/login" element={<Login />} />
        <Route path="/signup" element={<Signup />} />

        {/* Protected routes */}
        <Route
          path="/"
          element={
            <ProtectedRoute>
              <Layout>
                {/* Show different content based on role */}
                {roles.includes("ROLE_ADMIN") ? (
                  <UserList />
                ) : (
                  <Home /> // Create this component for regular users
                )}
              </Layout>
            </ProtectedRoute>
          }
        />

        {/* Admin-only routes */}
        <Route
          path="/users"
          element={
            <ProtectedRoute>
              <AdminRoute>
                <Layout>
                  <UserList />
                </Layout>
              </AdminRoute>
            </ProtectedRoute>
          }
        />

        <Route
          path="/users/add"
          element={
            <ProtectedRoute>
              <AdminRoute>
                <Layout>
                  <UserForm />
                </Layout>
              </AdminRoute>
            </ProtectedRoute>
          }
        />

        <Route
          path="/users/edit/:id"
          element={
            <ProtectedRoute>
              <AdminRoute>
                <Layout>
                  <UserForm />
                </Layout>
              </AdminRoute>
            </ProtectedRoute>
          }
        />

        {/* Catch-all route */}
        <Route
          path="*"
          element={<Navigate to={token ? "/" : "/login"} replace />}
        />
      </Routes>
    </Router>
  );
}

export default App;
